#!/bin/sh
# First start of the bundle's database: the application role (no
# BYPASSRLS: row-level security backs every tenant predicate). Its password
# is generated by the gateway (hex, so it needs no quoting). The migrations
# (run by ipam with the postgres role) grant it the ipam_* tables.
set -eu
psql -v ON_ERROR_STOP=1 --username postgres --dbname ipam <<SQL
CREATE EXTENSION IF NOT EXISTS timescaledb;
CREATE ROLE ipam_app LOGIN PASSWORD '${IPAM_APP_PASSWORD}' NOBYPASSRLS;
GRANT CONNECT ON DATABASE ipam TO ipam_app;
SQL
